<?php
// Loads environment — credentials come from config.local.php (gitignored, generated by CI).
if (file_exists(__DIR__ . '/config.local.php')) {
    require_once __DIR__ . '/config.local.php';
} else {
    die('config.local.php is missing — check deployment configuration.');
}

// Stubs so static analysis knows these constants exist — defined at runtime by config.local.php
if (!defined('GENERATE_PASSWORD')) define('GENERATE_PASSWORD', '');
if (!defined('DB_HOST'))           define('DB_HOST', '');
if (!defined('DB_NAME'))           define('DB_NAME', '');
if (!defined('DB_USER'))           define('DB_USER', '');
if (!defined('DB_PASS'))           define('DB_PASS', '');
